function t(path){return path.split('.').reduce((o,k)=>o?.[k],I18N[lang])||''}
function setText(sel,path){const el=document.querySelector(sel);if(el)el.innerHTML=t(path)}
function applyLanguage(){
 document.documentElement.lang=lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=t(el.dataset.i18n));
 document.querySelectorAll('[data-i18n-attr]').forEach(el=>{const [attr,path]=el.dataset.i18nAttr.split('|');el.setAttribute(attr,t(path));});
 document.querySelectorAll('.lang-btn').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
 const yearEl=document.querySelector('[data-year]');if(yearEl)yearEl.textContent=new Date().getFullYear();
 syncBookingControls();
 refreshLessonPreferenceLabels();
 renderAvailabilityPreview();
 if(window.renderCalendar)renderCalendar();
}
function setLanguage(next){lang=next;localStorage.setItem('thurstonLang',lang);applyLanguage()}
document.querySelectorAll('.lang-btn').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
const menu=document.querySelector('.menu-toggle');if(menu){menu.addEventListener('click',()=>document.querySelector('.nav-links').classList.toggle('open'))}
function monthKey(y,m){return `${y}-${String(m+1).padStart(2,'0')}`}
function pad(n){return String(n).padStart(2,'0')}
function dateKey(y,m,d){return `${y}-${pad(m+1)}-${pad(d)}`}
function daysInMonth(y,m){return new Date(y,m+1,0).getDate()}
function monthLabel(){return new Date(currentMonth.year,currentMonth.month,1).toLocaleDateString(lang==='de'?'de-CH':'en-GB',{month:'long',year:'numeric'})}
function timeToMinutes(v){const [h,m]=String(v).split(':').map(Number);return h*60+m}
function getDayData(key){
 const [y,m]=key.split('-').map(Number);
 const month=monthKey(y,m-1);
 return availabilityData[month]?.days?.[key] || null;
}
function isLoading(key){return loadingDays.has(key)}
function allSlots(key){
 const data=getDayData(key);
 if(!data || data.loading)return [];
 return data.slots||[];
}
function backendSlotType(){
 return sessionType==='hour'?'1h':sessionType==='half'?'half-day':'full-day';
}
function availableStarts(key){
 const data=getDayData(key);
 if(!data || data.loading || data.error)return [];
 const type=backendSlotType();
 return allSlots(key).filter(slot=>slot.type===type && (lessonPreference==='public' ? slot.available!==false : slot.privateAvailable===true || (!('privateAvailable' in slot) && !slot.sharedWithLevel))).map(slot=>slot.label);
}
function hasSlotType(key,type,id){
 return allSlots(key).some(slot=>slot.type===type && (!id || slot.id===id));
}
function statusForDay(key){
 const data=getDayData(key);
 if(!data || data.loading)return {className:'neutral',label:t('availability.checking')};
 if(data.error)return {className:'neutral',label:t('availability.errorTitle')};
 // Keep calendar labels independent of the customer's selected session, group size,
 // and lesson preference. Actual start times remain filtered in the slot panel.
 const slots=(data.slots||[]);
 if(!slots.length)return {className:'neutral',label:t('availability.full')};
 const fullDay=slots.some(slot=>slot.type==='full-day');
 if(fullDay)return {className:'neutral',label:t('availability.available')};
 const morning=slots.some(slot=>slot.id==='half-am' || (slot.type==='1h' && Number(slot.label.slice(0,2))<12));
 const afternoon=slots.some(slot=>slot.id==='half-pm' || (slot.type==='1h' && Number(slot.label.slice(0,2))>=12));
 if(morning && afternoon)return {className:'neutral',label:`${t('availability.morning')} · ${t('availability.afternoon')}`};
 if(morning)return {className:'neutral',label:t('availability.morning')};
 if(afternoon)return {className:'neutral',label:t('availability.afternoon')};
 return {className:'neutral',label:t('availability.available')};
}
(function ensureCalendarStatusColours(){
 if(document.querySelector('#ta-calendar-status-colours'))return;
 const style=document.createElement('style');style.id='ta-calendar-status-colours';
 // Calendar dates use one calm blue style; status words communicate the available windows.
 style.textContent='.day.neutral{background:#e7f2ff!important;border-color:#6ba8e8!important;color:#174c82!important}.day.selected{outline:3px solid #2477b9;outline-offset:1px}';
 document.head.appendChild(style);
})();
function reconcileSelectedDate(){
 if(selectedDate && !availableStarts(selectedDate).length){selectedDate=null;selectedSlot=null;}
}
(function ensureCalendarStatusColours(){
 if(document.querySelector('#ta-calendar-status-colours'))return;
 const style=document.createElement('style');style.id='ta-calendar-status-colours';
 style.textContent='.day.loading,.day.error{background:#e7f2ff!important;border-color:#6ba8e8!important;color:#174c82!important}.day.available,.day.partial{background:#e7f6ec!important;border-color:#62ad7b!important;color:#205b34!important}.day.booked{background:#fdeaea!important;border-color:#d97777!important;color:#842525!important}.day.selected{outline:3px solid #2477b9;outline-offset:1px}';
 document.head.appendChild(style);
})();
async function fetchMonthAvailabilityFor(year, monthIndex){
 const month=monthKey(year,monthIndex);
 if(availabilityData[month]?.loaded && !availabilityData[month]?.error)return availabilityData[month];
 availabilityData[month] ||= {days:{}};
 availabilityData[month].loading=true;
 const days=daysInMonth(year,monthIndex);
 for(let d=1;d<=days;d++)availabilityData[month].days[dateKey(year,monthIndex,d)]={loading:true,slots:[]};
 renderCalendar();
 try{
  const response=await fetch(`${API_BASE_URL}/api/availability/month?year=${year}&month=${monthIndex+1}`,{cache:'no-store'});
  if(!response.ok)throw new Error(`Month availability request failed: ${response.status}`);
  const payload=await response.json();
  for(let d=1;d<=days;d++){
   const key=dateKey(year,monthIndex,d);
   availabilityData[month].days[key]={loading:false,error:false,slots:payload.days?.[key]?.slots||[],capacity:payload.capacity||{}};
   availabilityCache.set(key,availabilityData[month].days[key]);
   loadingDays.delete(key);
  }
  availabilityData[month].loaded=true;availabilityData[month].loading=false;availabilityData[month].error=false;
  return availabilityData[month];
 }catch(error){
  console.error('Month availability check failed',month,error);
  for(let d=1;d<=days;d++){
   const key=dateKey(year,monthIndex,d);
   availabilityData[month].days[key]={loading:false,error:true,slots:[]};
   loadingDays.delete(key);
  }
  availabilityData[month].loaded=true;availabilityData[month].loading=false;availabilityData[month].error=true;
  return availabilityData[month];
 }finally{renderCalendar();}
}
async function fetchDayAvailability(key){
 const cached=availabilityCache.get(key);if(cached && !cached.error)return cached;
 const [y,m]=key.split('-').map(Number);
 const monthData=await fetchMonthAvailabilityFor(y,m-1);
 return monthData?.days?.[key] || {loading:false,error:true,slots:[]};
}
async function fetchMonthAvailability(){
 await fetchMonthAvailabilityFor(currentMonth.year,currentMonth.month);
}
function hasSelectedSlot(key){
 return selectedDate===key && selectedSlot;
}
function price(){return prices[sessionType][groupSize]}
function sessionLabel(){return sessionType==='hour'?t('availability.oneHour'):sessionType==='half'?t('availability.halfDay'):t('availability.fullDay')}
function peopleLabel(){return groupSize===1?`1 ${t('availability.person')}`:`${groupSize} ${t('availability.people')}`}
function syncBookingControls(){
 const type=document.querySelector('#session-type');const group=document.querySelector('#group-size');
 if(type){type.value=sessionType;type.options[0].textContent=`${t('availability.oneHour')} — CHF ${prices.hour[groupSize]}`;type.options[1].textContent=`${t('availability.halfDay')} — CHF ${prices.half[groupSize]}`;type.options[2].textContent=`${t('availability.fullDay')} — CHF ${prices.full[groupSize]}`;}
 if(group){group.value=String(groupSize);[1,2,3,4].forEach((n,i)=>{if(group.options[i])group.options[i].textContent=`${n} ${n===1?t('availability.person'):t('availability.people')}`})}
 const bp=document.querySelector('#booking-price');if(bp)bp.innerHTML=`<span>${t('availability.priceLabel')}</span><strong>CHF ${price()}</strong>`;
 updateHiddenBookingFields();
}
function renderCalendar(){
 const grid=document.querySelector('#calendar-grid');if(!grid)return;
 const monthTitle=document.querySelector('#calendar-month');if(monthTitle)monthTitle.textContent=monthLabel();
 grid.innerHTML='';
 ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].forEach((d,i)=>{const el=document.createElement('div');el.className='weekday';el.textContent=lang==='de'?['Mo','Di','Mi','Do','Fr','Sa','So'][i]:d;grid.appendChild(el)});
 const first=new Date(currentMonth.year,currentMonth.month,1), start=(first.getDay()+6)%7, days=daysInMonth(currentMonth.year,currentMonth.month);
 for(let i=0;i<start;i++){const el=document.createElement('div');el.className='day muted';grid.appendChild(el)}
 for(let d=1;d<=days;d++){
  const key=dateKey(currentMonth.year,currentMonth.month,d), data=getDayData(key), status=statusForDay(key), el=document.createElement('div');
  const selectable=!!(data && !data.loading && !data.error && (data.slots||[]).length);
  el.className=`day ${status.className}${selectedDate===key?' selected':''}`;
  el.dataset.date=key;
  el.setAttribute('role','button');
  el.setAttribute('tabindex', selectable ? '0' : '-1');
  el.innerHTML=`<span class="day-number">${d}</span><span class="day-status">${status.label}</span>`;
  if(selectable){
   el.setAttribute('aria-label',`${key} — ${status.label}`);
   el.style.pointerEvents='auto';
   el.style.cursor='pointer';
   el.onclick=()=>selectDate(key);
   el.onkeydown=(event)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectDate(key);}};
  }
  grid.appendChild(el);
 }
 while(grid.children.length%7){const el=document.createElement('div');el.className='day muted';grid.appendChild(el)}
 updateSlotPanel();
}
async function selectDate(key){
 const data=getDayData(key);
 if(!data || data.loading || data.error)return;
 selectedDate=key;
 selectedSlot=null;
 renderCalendar();
 const panel=document.querySelector('#slot-panel');
 if(panel) panel.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function handleCalendarDayClick(event){
 const day=event.target.closest('.day[data-date]');
 if(!day || day.classList.contains('muted'))return;
 const key=day.dataset.date;
 const data=getDayData(key);
 if(!data || data.loading || data.error || !(data.slots||[]).length)return;
 selectDate(key);
}
function handleCalendarKeydown(event){
 if(event.key!=='Enter' && event.key!==' ')return;
 const day=event.target.closest('.day[data-date]');
 if(!day || day.classList.contains('muted'))return;
 event.preventDefault();
 handleCalendarDayClick(event);
}


function ensureBookingModal(){
 let modal=document.querySelector('#shared-session-modal');
 if(modal)return modal;
 modal=document.createElement('div');
 modal.id='shared-session-modal';
 modal.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(9,20,30,.62);display:none;align-items:center;justify-content:center;padding:20px;';
 modal.innerHTML=`<div role="dialog" aria-modal="true" aria-labelledby="shared-modal-title" style="background:#fff;color:#17232d;max-width:520px;width:100%;border-radius:18px;padding:26px;box-shadow:0 20px 70px rgba(0,0,0,.25)">
 <h2 id="shared-modal-title" style="margin:0 0 14px;font-size:1.5rem"></h2>
 <p id="shared-modal-copy" style="line-height:1.6"></p>
 <p id="shared-modal-capacity" style="font-size:.9rem;color:#53616b"></p>
 <div style="display:grid;gap:10px;margin-top:20px">
 <button type="button" class="btn" id="shared-modal-continue"></button>
 <button type="button" class="btn btn-secondary" id="shared-modal-cancel"></button>
 </div></div>`;
 document.body.appendChild(modal);
 modal.addEventListener('click',e=>{if(e.target===modal)closeBookingModal();});
 modal.querySelector('#shared-modal-cancel').addEventListener('click',closeBookingModal);
 return modal;
}
function closeBookingModal(){
 const modal=document.querySelector('#shared-session-modal');
 if(modal)modal.style.display='none';
 pendingSharedWarning=null;
}
function levelName(code){
 const map={B:lang==='de'?'Anfänger':'Beginner',I:lang==='de'?'Fortgeschritten':'Intermediate',A:lang==='de'?'Sehr fortgeschritten':'Advanced'};
 return map[code]|| (lang==='de'?'unbekannt':'unknown');
}
function openSharedWarning(level, slotLabel){
 const modal=ensureBookingModal();
 pendingSharedWarning={level,slotLabel};
 modal.querySelector('#shared-modal-title').textContent=t('bookingPage.shareWarningTitle');
 modal.querySelector('#shared-modal-copy').textContent=`${t('bookingPage.shareWarningLead')} ${levelName(level)} ${t('bookingPage.shareWarningTail')}`;
 modal.querySelector('#shared-modal-capacity').textContent=t('bookingPage.publicNote');
 modal.querySelector('#shared-modal-continue').textContent=t('bookingPage.shareWarningContinue');
 modal.querySelector('#shared-modal-cancel').textContent=t('bookingPage.chooseAnother');
 modal.querySelector('#shared-modal-continue').onclick=()=>{closeBookingModal();createTemporaryHold(slotLabel);};
 modal.style.display='flex';
}
async function createTemporaryHold(slotLabel){
 if(groupSize > 1 && lessonPreference === 'public'){ lessonPreference='private'; const pref=document.querySelector('#lesson-preference'); if(pref)pref.value='private'; }
 if(activeHold){ await releaseActiveHold(false); }
 const slotId=findSelectedSlotId(slotLabel);
 if(!slotId){ alert(t('bookingPage.holdFailed')); return; }
 const button=document.querySelector('#request-slot');
 if(button){button.disabled=true;button.textContent=lang==='de'?'Wird reserviert…':'Creating hold…';}
 try{
  const response=await fetch(`${API_BASE_URL}/api/hold`,{
   method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},
   body:JSON.stringify({date:selectedDate,slotId,state:lessonPreference,people:groupSize,level:ridingLevel})
  });
  const payload=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(payload.error||'Hold could not be created');
  activeHold={id:payload.hold.id,expiresAt:payload.hold.expiresAt,slotLabel,date:selectedDate,slotId,state:lessonPreference,people:groupSize,level:ridingLevel};
  availabilityCache.delete(selectedDate);
  const heldMonth=monthKey(Number(selectedDate.slice(0,4)),Number(selectedDate.slice(5,7))-1);
  if(availabilityData[heldMonth]?.days)delete availabilityData[heldMonth].days[selectedDate];if(availabilityData[heldMonth])availabilityData[heldMonth].loaded=false;
  revealBookingEnquiry();
 }catch(error){
  console.error('Unable to hold selected slot',error);
  alert(t('bookingPage.holdFailed'));
  selectedSlot=null;renderCalendar();
 }
}
function findSelectedSlotId(slotLabel){
 const data=getDayData(selectedDate);
 const match=(data?.slots||[]).find(slot=>slot.label===slotLabel && slot.type===backendSlotType());
 return match?.id||'';
}
function revealBookingEnquiry(){
 const section=document.querySelector('.booking-form-section');
 if(section)section.style.display='';
 updateBookingSummary();
 const summary=document.querySelector('#booking-summary');
 if(summary && activeHold){
  const expiry=new Date(activeHold.expiresAt).toLocaleTimeString(lang==='de'?'de-CH':'en-GB',{hour:'2-digit',minute:'2-digit'});
  summary.textContent=`${summary.textContent} · ${t('bookingPage.holdCreated')} ${expiry}`;
  let cancel=document.querySelector('#cancel-booking-hold');
  if(!cancel){cancel=document.createElement('button');cancel.type='button';cancel.id='cancel-booking-hold';cancel.className='btn btn-secondary';cancel.style.marginTop='10px';summary.insertAdjacentElement('afterend',cancel);cancel.addEventListener('click',()=>releaseActiveHold(true));}
  cancel.textContent=lang==='de'?'Zeit freigeben':'Release held time';
 }
 section?.scrollIntoView({behavior:'smooth',block:'start'});
}

async function releaseActiveHold(showMessage=true){
 if(!activeHold)return;
 const oldHold=activeHold;
 activeHold=null;
 try{
  const response=await fetch(`${API_BASE_URL}/api/hold/${encodeURIComponent(oldHold.id)}`,{method:'DELETE',cache:'no-store'});
  if(!response.ok){const payload=await response.json().catch(()=>({}));throw new Error(payload.error||'Could not release hold');}
 }catch(error){console.warn('Could not release temporary hold; it will expire automatically.',error);}
 const section=document.querySelector('.booking-form-section');if(section)section.style.display='none';
 const cancel=document.querySelector('#cancel-booking-hold');if(cancel)cancel.remove();
 availabilityCache.delete(oldHold.date);
 const m=monthKey(Number(oldHold.date.slice(0,4)),Number(oldHold.date.slice(5,7))-1);
 if(availabilityData[m]?.days)delete availabilityData[m].days[oldHold.date];if(availabilityData[m])availabilityData[m].loaded=false;
 if(showMessage)alert(lang==='de'?'Die reservierte Zeit wurde freigegeben.':'Your held time has been released.');
 if(oldHold.date)fetchDayAvailability(oldHold.date);
}

(function wireBookingSubmission(){
 const form=document.querySelector('.booking-form-section form');
 if(!form)return;
 form.removeAttribute('action');
 form.removeAttribute('method');
 let status=document.querySelector('#booking-submit-status');
 if(!status){status=document.createElement('p');status.id='booking-submit-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.appendChild(status);}
 form.addEventListener('submit',async event=>{
  event.preventDefault();
  if(!activeHold){status.textContent=lang==='de'?'Bitte wähle zuerst eine Zeit und reserviere sie vorübergehend.':'Please select a time and create a temporary hold first.';return;}
  if(Date.parse(activeHold.expiresAt)<=Date.now()){
   await releaseActiveHold(false);status.textContent=t('bookingPage.holdExpired');return;
  }
  const submit=form.querySelector('button[type="submit"]');
  if(submit){submit.disabled=true;submit.textContent=lang==='de'?'Wird gesendet…':'Sending enquiry…';}
  status.textContent='';
  const data=new FormData(form);
  const payload={holdId:activeHold.id,name:data.get('Name'),email:data.get('Email'),phone:data.get('Phone')||'',notes:data.get('Message')||'',level:data.get('Riding level')||'Not sure'};
  try{
   const response=await fetch(`${API_BASE_URL}/api/book`,{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
   const result=await response.json().catch(()=>({}));
   if(!response.ok){if(response.status===409 && /expired|hold/i.test(result.error||'')){await releaseActiveHold(false);status.textContent=t('bookingPage.holdExpired');}else{throw new Error(result.error||'Booking enquiry could not be submitted.');}return;}
   activeHold=null;
   const cancel=document.querySelector('#cancel-booking-hold');if(cancel)cancel.remove();
   form.querySelectorAll('input,select,textarea,button').forEach(control=>control.disabled=true);
   const emailSent=result.booking?.emailSent===true;
   status.textContent=lang==='de'
    ? (emailSent?'Vielen Dank! Deine Buchungsanfrage wurde gespeichert. Eine Benachrichtigung wurde gesendet.':'Vielen Dank! Deine Buchungsanfrage wurde gespeichert. Die E-Mail-Benachrichtigung konnte nicht gesendet werden; ich prüfe das.')
    : (emailSent?'Thank you! Your booking enquiry has been recorded and an email notification has been sent.':'Thank you! Your booking enquiry has been recorded, but the email notification could not be sent. The booking is still saved.');
   if(submit){submit.disabled=true;submit.textContent=lang==='de'?'Anfrage gespeichert ✓':'Enquiry recorded ✓';}
   const heldDate=selectedDate;availabilityCache.delete(heldDate);
   const m=monthKey(Number(heldDate.slice(0,4)),Number(heldDate.slice(5,7))-1);if(availabilityData[m]?.days)delete availabilityData[m].days[heldDate];if(availabilityData[m])availabilityData[m].loaded=false;
   await fetchDayAvailability(heldDate);
  }catch(error){console.error('Booking submission failed',error);status.textContent=error.message||'Please try again. Your hold remains active if it has not expired.';}
  finally{if(submit && activeHold){submit.disabled=false;submit.textContent=t('bookingPage.button');}}
 });
})();

function updateSlotPanel(){
 const panel=document.querySelector('#slot-panel');if(!panel)return;
 if(!selectedDate){
   panel.innerHTML=`<div><h3>${t('availability.select')}</h3><p class="availability-note">${t('availability.liveNote')}</p></div>`;
   updateHiddenBookingFields();return;
 }
 const data=getDayData(selectedDate);
 if(!data || data.loading){
   panel.innerHTML=`<div><h3>${t('availability.checking')}</h3></div>`;
   updateHiddenBookingFields();return;
 }
 if(data.error){
   panel.innerHTML=`<div><h3>${t('availability.errorTitle')}</h3><p class="availability-note">${t('availability.errorText')}</p></div>`;
   updateHiddenBookingFields();return;
 }
 const s=availableStarts(selectedDate);
 const dateLabel=new Date(selectedDate+'T12:00:00').toLocaleDateString(lang==='de'?'de-CH':'en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 if(!s.length){
   panel.innerHTML=`<div><div class="slot-heading"><div><h3>${dateLabel}</h3><p>${t('availability.full')}</p></div></div><p class="availability-note">${t('availability.noTimes')}</p></div>`;
   updateHiddenBookingFields();return;
 }
 panel.innerHTML=`<div><div class="slot-heading"><div><h3>${dateLabel}</h3><p>${sessionLabel()} · ${peopleLabel()} · CHF ${price()}</p></div><span class="slot-duration">${sessionMeta[sessionType].hours} ${sessionMeta[sessionType].hours===1?t('availability.hourUnit'):t('availability.hoursUnit')}</span></div><div class="slots">${s.map(x=>`<button class="slot ${selectedSlot===x?'chosen':''}" data-slot="${x}">${x}</button>`).join('')}</div><p class="availability-note">${t('availability.liveNote')}</p></div><div><button class="btn" id="request-slot" ${selectedSlot?'':'disabled'}>${t('availability.request')}</button></div>`;
 panel.querySelectorAll('.slot').forEach(b=>b.addEventListener('click',()=>{selectedSlot=b.dataset.slot;updateSlotPanel()}));
 const req=panel.querySelector('#request-slot');if(req)req.addEventListener('click',()=>{
  if(!selectedSlot)return;
  const chosen=(data.slots||[]).find(slot=>slot.label===selectedSlot && slot.type===backendSlotType());
  if(lessonPreference==='public' && chosen && chosen.sharedWithLevel){
    openSharedWarning(chosen.sharedWithLevel,selectedSlot);
  }else{
    createTemporaryHold(selectedSlot);
  }
 });
 updateHiddenBookingFields();
}
function updateBookingSummary(){
 const summary=document.querySelector('#booking-summary');if(!summary)return;
 if(!selectedDate||!selectedSlot){summary.textContent=`${sessionLabel()} · ${peopleLabel()} · CHF ${price()} — ${t('availability.select')}`;return}
 const dateLabel=new Date(selectedDate+'T12:00:00').toLocaleDateString(lang==='de'?'de-CH':'en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
 summary.textContent=`${sessionLabel()} · ${peopleLabel()} · CHF ${price()} · ${dateLabel} · ${selectedSlot}`;
}
function updateHiddenBookingFields(){
 const vals={sessionLabel:sessionLabel(),group:peopleLabel(),time:selectedDate&&selectedSlot?`${selectedDate} ${selectedSlot}`:'',price:`CHF ${price()}`};
 const a=document.querySelector('#booking-session'),b=document.querySelector('#booking-people'),c=document.querySelector('#booking-time'),d=document.querySelector('#booking-price-hidden');
 if(a)a.value=vals.sessionLabel;if(b)b.value=vals.group;if(c)c.value=vals.time;if(d)d.value=vals.price;
 updateBookingSummary();
}
function changeMonth(delta){
 let m=currentMonth.month+delta,y=currentMonth.year;if(m<0){m=11;y--}if(m>11){m=0;y++}
 currentMonth={year:y,month:m};selectedDate=null;selectedSlot=null;renderCalendar();fetchMonthAvailability();
}

// The enquiry form stays hidden until the backend confirms a temporary hold.
(function gateBookingEnquiry(){
 const section=document.querySelector('.booking-form-section');
 if(section && !activeHold)section.style.display='none';
})();

window.renderCalendar=renderCalendar;

function refreshLessonPreferenceLabels(){
 const wrap=document.querySelector('#lesson-preference-controls');if(!wrap)return;
 const privateButton=wrap.querySelector('[data-preference="private"]');
 const sharedButton=wrap.querySelector('[data-preference="public"]');
 if(privateButton){privateButton.querySelector('strong').textContent=t('bookingPage.privateOption');privateButton.querySelector('span').textContent=t('bookingPage.privateTagline');}
 if(sharedButton){sharedButton.querySelector('strong').textContent=t('bookingPage.shareOption');sharedButton.querySelector('span').textContent=t('bookingPage.sharedTagline');}
 const help=wrap.querySelector('#lesson-preference-help');if(help)help.textContent=t(lessonPreference==='private'?'bookingPage.privateHelp':'bookingPage.shareHelp');
 syncLessonPreferenceButtons();
}
function syncLessonPreferenceButtons(){
 document.querySelectorAll('#lesson-preference-controls [data-preference]').forEach(button=>{
  const selected=button.dataset.preference===lessonPreference;
  button.setAttribute('aria-pressed',String(selected));
  button.style.borderColor=selected?'#2477b9':'#b8c5d1';
  button.style.boxShadow=selected?'0 0 0 2px rgba(36,119,185,.18)':'none';
  button.style.background=selected?'#eef7ff':'#fff';
 });
}
// Private/shared choice buttons. Detailed descriptions live on the Lessons page.
(function injectLessonPreferenceControls(){
 const host=document.querySelector('.booking-options');
 if(!host || document.querySelector('#lesson-preference-controls'))return;
 const wrap=document.createElement('div');
 wrap.id='lesson-preference-controls';wrap.className='lesson-preference-controls';
 wrap.style.cssText='grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:10px;';
 wrap.innerHTML=`
  <button type="button" class="lesson-choice" data-preference="private" aria-pressed="false" style="text-align:left;padding:16px;border:1px solid #b8c5d1;border-radius:12px;background:#fff;color:#17232d;cursor:pointer">
   <strong style="display:block;margin-bottom:6px">${t('bookingPage.privateOption')}</strong><span>${t('bookingPage.privateTagline')}</span>
  </button>
  <button type="button" class="lesson-choice" data-preference="public" aria-pressed="false" style="text-align:left;padding:16px;border:1px solid #b8c5d1;border-radius:12px;background:#fff;color:#17232d;cursor:pointer">
   <strong style="display:block;margin-bottom:6px">${t('bookingPage.shareOption')}</strong><span>${t('bookingPage.sharedTagline')}</span>
  </button>
  <p class="availability-note" id="lesson-preference-help" style="grid-column:1/-1;margin:0"></p>`;
 host.appendChild(wrap);
 wrap.querySelectorAll('[data-preference]').forEach(button=>button.addEventListener('click',async()=>{
  const next=button.dataset.preference;
  if(next==='public' && groupSize>1){
   const help=document.querySelector('#lesson-preference-help');if(help)help.textContent=t('bookingPage.sharedSingleOnly');return;
  }
  if(activeHold)await releaseActiveHold(false);
  lessonPreference=next;selectedSlot=null;reconcileSelectedDate();
  syncBookingControls();renderCalendar();
  const help=document.querySelector('#lesson-preference-help');if(help)help.textContent=t(next==='private'?'bookingPage.privateHelp':'bookingPage.shareHelp');
  wrap.querySelectorAll('[data-preference]').forEach(b=>{
   const selected=b.dataset.preference===lessonPreference;
   b.setAttribute('aria-pressed',String(selected));
   b.style.borderColor=selected?'#2477b9':'#b8c5d1';
   b.style.boxShadow=selected?'0 0 0 2px rgba(36,119,185,.18)':'none';
   b.style.background=selected?'#eef7ff':'#fff';
  });
  fetchMonthAvailability();
 }));
 const syncButtons=()=>wrap.querySelectorAll('[data-preference]').forEach(b=>{
  const selected=b.dataset.preference===lessonPreference;b.setAttribute('aria-pressed',String(selected));
  b.style.borderColor=selected?'#2477b9':'#b8c5d1';b.style.background=selected?'#eef7ff':'#fff';
 });
 syncButtons();
 const help=document.querySelector('#lesson-preference-help');if(help)help.textContent=t(lessonPreference==='private'?'bookingPage.privateHelp':'bookingPage.shareHelp');
})();

const calendarGrid=document.querySelector('#calendar-grid');
if(calendarGrid){
 calendarGrid.addEventListener('click',handleCalendarDayClick);
 calendarGrid.addEventListener('keydown',handleCalendarKeydown);
}
const sessionControl=document.querySelector('#session-type');if(sessionControl)sessionControl.addEventListener('change',async e=>{if(activeHold)await releaseActiveHold(false);sessionType=e.target.value;selectedSlot=null;reconcileSelectedDate();syncBookingControls();renderCalendar();fetchMonthAvailability()});
const groupControl=document.querySelector('#group-size');if(groupControl)groupControl.addEventListener('change',async e=>{if(activeHold)await releaseActiveHold(false);groupSize=Number(e.target.value);if(groupSize>1)lessonPreference='private';selectedSlot=null;reconcileSelectedDate();syncBookingControls();refreshLessonPreferenceLabels();renderCalendar();fetchMonthAvailability()});
const prev=document.querySelector('#prev-month');if(prev)prev.addEventListener('click',()=>changeMonth(-1));
const next=document.querySelector('#next-month');if(next)next.addEventListener('click',()=>changeMonth(1));
async function renderAvailabilityPreview(){
 const el=document.querySelector('#availability-preview-list'); if(!el)return;
 el.innerHTML=`<div class="availability-mini-date"><span>${t('availability.checking')}</span></div>`;
 const today=new Date(); today.setHours(12,0,0,0);
 const dates=[];
 // Exclude today and tomorrow; show upcoming availability from the day after tomorrow.
 for(let offset=2;offset<47 && dates.length<6;offset++){
   const date=new Date(today);date.setDate(today.getDate()+offset);
   const key=`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`;
   const data=await fetchDayAvailability(key);
   if(data && !data.error && availableStarts(key).length)dates.push(key);
 }
 el.innerHTML=dates.map(key=>{
   const date=new Date(key+'T12:00:00');
   const label=date.toLocaleDateString(lang==='de'?'de-CH':'en-GB',{weekday:'short',day:'numeric',month:'short'});
   return `<div class="availability-mini-date"><strong>${label}</strong><span>${statusForDay(key).label}</span></div>`;
 }).join('') || `<div class="availability-mini-date"><span>${t('availability.full')}</span></div>`;
}
applyLanguage();
if(document.querySelector('#calendar-grid')){renderCalendar();fetchMonthAvailability();}

// V7: keep the home navigation available while scrolling, while changing it to a solid alpine header.
(function(){
 const header=document.querySelector('.home-header');
 if(header){
   const sync=()=>{
     const scrolled=(window.pageYOffset || document.documentElement.scrollTop || 0)>40;
     header.classList.toggle('is-scrolled',scrolled);
     document.body.classList.toggle('home-scrolled',scrolled);
   };
   sync();
   window.addEventListener('scroll',sync,{passive:true});
   window.addEventListener('pageshow',sync);
   window.addEventListener('resize',sync,{passive:true});
 }

 // V7: click-to-enlarge gallery images. The full-resolution source is shown in the lightbox.
 const box=document.querySelector('#lightbox'), image=document.querySelector('#lightbox-image'), caption=document.querySelector('#lightbox-caption');
 if(box && image){
   document.querySelectorAll('.photo img').forEach(img=>img.addEventListener('click',()=>{
     image.src=img.currentSrc||img.src;
     image.alt=img.alt||'';
     caption.textContent=img.alt||'';
     box.classList.add('open'); box.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden';
   }));
   const close=()=>{box.classList.remove('open');box.setAttribute('aria-hidden','true');image.src='';document.body.style.overflow='';};
   box.addEventListener('click',e=>{if(e.target===box)close()});
   box.querySelector('.lightbox-close').addEventListener('click',close);
   document.addEventListener('keydown',e=>{if(e.key==='Escape'&&box.classList.contains('open'))close()});
 }
})();
